<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watchEffect } from 'vue';
import { NConfigProvider, darkTheme } from 'naive-ui';
import { desktop, invoke, listen, type Settings } from '../../bridge.ts';
import { accent, followAccent, followHost, isDark } from '../appearance.ts';
import { applyUiTokens } from '../design-tokens.ts';
import { themeFor } from '../theme.ts';
import { closeConfigurationWindow } from '../configuration/windows.ts';
interface Ref { pack_id:number;version:number }
interface Widget {id:string;kind:string;x:number;y:number;scale:number;enabled:boolean}
interface Local {id:string;title:string;created_at:string;snapshot:{wallpaper_id:string;effects:{selected:string};widgets:Widget[]}|null;refs:Ref[];cloud_revision:number}
interface Cloud {id:string;title:string;revision:number;updated_at:string;items:{pack_id:number;version:number;available:boolean;title?:string}[]}
interface Pack {id:number;title:string;kind:string;version:number}
const items=ref<Local[]>([]),packs=ref<Pack[]>([]),remote=ref<Cloud[]>([]),remoteTotal=ref(0),cloudPage=ref(1),title=ref(''),selected=ref<number[]>([]),active=ref(''),enabled=ref(false),signedIn=ref(false),busy=ref(false),message=ref(''),error=ref(''),confirm=ref<{kind:'restore'|'remove'|'cloud-remove'|'cloud-adopt';row:Local|Cloud}|null>(null);
const current=computed(()=>items.value.find(v=>v.id===active.value));
const labels:Record<string,string>={clock:'时钟',weather:'天气',notes:'便签',reminders:'提醒',stocks:'行情',woodfish:'木鱼',calendar:'日历',countdown:'纪念日',custom:'自定义组件'};
const offs:(()=>void)[]=[];
let epoch=0;
watchEffect(()=>{applyUiTokens(isDark.value,accent.value);document.documentElement.dataset.theme=isDark.value?'dark':'light'});
const text=(e:unknown)=>e instanceof Error?e.message:String(e);
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=text(e)}finally{busy.value=false}}
async function status(){const mine=epoch;const data=await invoke<{items:Local[];cloud_enabled:boolean;signed_in:boolean}>('community_schemes_status');if(mine!==epoch)return;items.value=data.items;enabled.value=data.cloud_enabled;signedIn.value=data.signed_in;if(!items.value.some(v=>v.id===active.value))active.value=items.value[0]?.id??'';}
async function loadCloud(){if(!enabled.value)return;const mine=epoch;const data=await invoke<{items:Cloud[];total:number}>('community_schemes_cloud',{action:'list',id:null,revision:null,page:cloudPage.value});if(mine!==epoch||!enabled.value)return;remote.value=data.items;remoteTotal.value=data.total;}
async function reload(){await act(async()=>{await status();if(enabled.value)await loadCloud()})}
async function save(){await act(async()=>{const refs=packs.value.filter(v=>selected.value.includes(v.id)).map(v=>({pack_id:v.id,version:v.version}));const out=await invoke<{id:string}>('community_schemes_save',{title:title.value,refs});await status();active.value=out.id;title.value='';selected.value=[];message.value='已保存到本机。尚未上传到云端。'})}
async function toggle(){const next=!enabled.value;await act(async()=>{await invoke('community_schemes_cloud_enabled',{enabled:next});await status();if(next){await loadCloud();message.value='已允许访问账号方案备份。选择具体方案后才能上传。'}else{remote.value=[];message.value='已关闭云端访问，已有云端备份会保留。'}})}
async function upload(row:Local){await act(async()=>{await invoke('community_schemes_cloud',{action:'save',id:row.id,revision:row.cloud_revision,page:null});await status();await loadCloud();message.value='选中的社区作品引用已保存到账号。桌面布局保留在本机。'})}
async function confirmed(){const request=confirm.value;if(!request)return;confirm.value=null;await act(async()=>{if(request.kind==='restore'){const out=await invoke<{warnings:string[];message:string}>('community_schemes_restore',{id:request.row.id});message.value=[out.message,...out.warnings].join('\n');}else if(request.kind==='remove'){await invoke('community_schemes_remove',{id:request.row.id});await status();message.value='本地方案已移除，云端备份保持原样。'}else if(request.kind==='cloud-adopt'){await invoke('community_schemes_cloud',{action:'adopt',id:request.row.id,revision:null,page:null});await status();message.value='云端作品引用已带回本机。查看作品后可逐项应用。';}else{await invoke('community_schemes_cloud',{action:'remove',id:request.row.id,revision:(request.row as Cloud).revision,page:null});await status();await loadCloud();message.value='云端方案已移到回收站，本地方案保留。'}})}
function openPack(id:number){void invoke('open_download_url',{url:`https://chat.xiangban.xyz/packs/${id}`}).catch(e=>error.value=text(e))}
function changePage(next:number){cloudPage.value=next;void act(loadCloud)}
onMounted(async()=>{if(!desktop){error.value='请在小伴桌面打开此窗口；方案保存与恢复需要本机权限。';return;}await act(async()=>{const s=await invoke<Settings>('get_settings');followHost(s.appearance);followAccent(s.accent);await status();const list=await invoke<{items:Pack[]}>('community_browse',{path:'/api/packs?sort=hot&page_size=50'}).catch(()=>({items:[]}));packs.value=list.items;if(enabled.value)await loadCloud();});offs.push(await listen<Settings>('settings-changed',s=>{followHost(s.appearance);followAccent(s.accent)}));offs.push(await listen('account-changed',()=>{++epoch;confirm.value=null;remote.value=[];enabled.value=false;signedIn.value=false;void status().catch(e=>error.value=text(e))}));});
onBeforeUnmount(()=>{++epoch;offs.forEach(off=>off())});
</script>
<template>
<NConfigProvider :theme="isDark?darkTheme:null" :theme-overrides="themeFor(isDark,accent)">
<main class="schemes-window">
<header><div><p class="eyebrow">社区 · 本地优先</p><h1>我的桌面方案</h1></div><button class="button" @click="closeConfigurationWindow">关闭</button></header>
<div v-if="error" class="notice error" role="alert">{{error}}</div><div v-if="message" class="notice" role="status">{{message}}</div>
<section v-if="confirm" class="confirm" role="alertdialog" aria-label="确认方案操作"><strong>{{confirm.kind==='restore'?'还原这份本地方案？':confirm.kind==='remove'?'移除本地方案？':confirm.kind==='cloud-adopt'?'恢复云端作品引用到本机？':'移除云端备份？'}}</strong><p>{{confirm.row.title}}<template v-if="confirm.kind==='restore'"> · 将切换壁纸、特效和伙伴主题，并按比例移动仍存在的组件。缺失资源会跳过，便签和提醒正文保持原样。</template></p><div class="actions"><button class="button primary" :disabled="busy" @click="confirmed">确认</button><button class="button" @click="confirm=null">取消</button></div></section>
<div class="workspace"><aside>
<form class="capture" @submit.prevent="save"><h2>保存当前桌面</h2><label>方案名称<input v-model="title" maxlength="60" required placeholder="例如：专注工作桌面" :disabled="busy"></label><details><summary>关联社区作品（可选，最多20项）</summary><p>请选择这套桌面用到的已发布作品。只勾选需要备份到账号的引用。</p><p v-if="!packs.length">暂时没有可关联作品；仍可保存本地布局。</p><label v-for="pack in packs" :key="pack.id" class="check"><input v-model="selected" type="checkbox" :value="pack.id" :disabled="busy||(!selected.includes(pack.id)&&selected.length>=20)">{{pack.title}} <small>v{{pack.version}}</small></label></details><button class="button primary" type="submit" :disabled="busy||!desktop">保存到本机</button></form>
<div class="local-head"><h2>本地方案 <small>{{items.length}}</small></h2><button class="link" :disabled="busy" @click="reload">刷新</button></div><p v-if="!items.length" class="empty">还没有保存方案。</p><ul class="local-list"><li v-for="row in items" :key="row.id"><button :class="{selected:active===row.id}" @click="active=row.id"><strong>{{row.title}}</strong><small>{{new Date(row.created_at).toLocaleDateString()}} · {{row.snapshot?.widgets.length??0}}个组件</small></button></li></ul>
</aside><section class="detail">
<template v-if="current"><div class="detail-heading"><h2>{{current.title}}</h2><span class="badge">保存在本机</span></div><div v-if="current.snapshot" class="desktop-preview" aria-label="组件相对位置预览"><span class="preview-wall">壁纸 {{current.snapshot.wallpaper_id||'系统桌面'}}</span><span v-for="widget in current.snapshot.widgets.filter(v=>v.enabled)" :key="widget.id" class="preview-widget" :style="{left:`${Math.min(widget.x*100,75)}%`,top:`${Math.min(widget.y*100,80)}%`}">{{labels[widget.kind]??widget.kind}}</span><span class="preview-effect">特效 {{current.snapshot.effects.selected||'未开启'}}</span></div><p class="hint">组件按相对位置还原，分辨率变化时可能需要调整。预览只画布局，不截取其他应用画面。</p><div class="actions"><button class="button primary" :disabled="busy||!current.snapshot" @click="confirm={kind:'restore',row:current}">查看并还原</button><button class="button" :disabled="busy" @click="confirm={kind:'remove',row:current}">移除本地方案</button></div><h3>关联作品</h3><p v-if="!current.refs.length" class="hint">未关联社区作品，当前方案只在本机使用。</p><button v-for="ref in current.refs" :key="ref.pack_id" class="reference" @click="openPack(ref.pack_id)">查看社区作品 #{{ref.pack_id}} · v{{ref.version}}</button>
</template><p v-else class="empty">保存桌面后，在这里预览和还原。</p>
<section class="cloud"><div class="detail-heading"><h2>账号方案备份</h2><button v-if="signedIn" class="button" :disabled="busy" :aria-pressed="enabled" @click="toggle">{{enabled?'已开启，点击关闭':'开启云端备份'}}</button><button v-else class="button" @click="invoke('configuration_window_login')">登录后开启</button></div><p class="hint">默认关闭。开启后读取备份，点击备份才上传选中的社区作品编号、版本和方案名称；桌面布局、壁纸文件、便签、聊天、资料库和密钥留在本机。</p><template v-if="enabled"><button class="button primary" :disabled="busy||!current?.refs.length" @click="current&&upload(current)">备份当前方案的作品引用</button><button class="button" :disabled="busy" @click="act(loadCloud)">刷新云端</button><p v-if="!remote.length" class="empty">账号里还没有方案备份。</p><article v-for="row in remote" :key="row.id" class="remote"><h3>{{row.title}}</h3><p class="hint">版本{{row.revision}} · {{new Date(row.updated_at).toLocaleString()}}</p><template v-for="ref in row.items" :key="ref.pack_id"><button v-if="ref.available" class="reference" @click="openPack(ref.pack_id)">{{ref.title}} · v{{ref.version}}</button><p v-else class="hint">作品 #{{ref.pack_id}} 已不可用，无法从备份绕过下架限制。</p></template><button class="link" :disabled="busy" @click="confirm={kind:'cloud-adopt',row}">恢复引用到本机</button><button class="link danger" :disabled="busy" @click="confirm={kind:'cloud-remove',row}">移到云端回收站</button></article><div v-if="remoteTotal>50" class="actions"><button class="button" :disabled="busy||cloudPage<=1" @click="changePage(cloudPage-1)">上一页</button><span>{{cloudPage}}</span><button class="button" :disabled="busy||cloudPage*50>=remoteTotal" @click="changePage(cloudPage+1)">下一页</button></div></template></section>
</section></div></main></NConfigProvider>
</template>
<style scoped>
.schemes-window{min-height:100vh;background:var(--ui-app-bg);color:var(--ui-text);font-size:13px;padding:24px}header,.detail-heading,.local-head{display:flex;align-items:center;justify-content:space-between;gap:12px}header{margin-bottom:24px}h1{font-size:22px;margin:4px 0 0}h2{font-size:15px;margin:0}h3{font-size:13px;margin:20px 0 10px}.eyebrow,.hint,.empty,small{font-size:12px;color:var(--ui-text-secondary)}.eyebrow{margin:0}.hint{line-height:1.8}.workspace{display:grid;grid-template-columns:280px minmax(0,1fr);gap:24px}.workspace>aside{border-right:1px solid var(--ui-border);padding-right:24px}.capture{display:grid;gap:14px;padding-bottom:24px;border-bottom:1px solid var(--ui-border)}label{display:grid;gap:7px}input:not([type=checkbox]){width:100%;box-sizing:border-box;border:1px solid var(--ui-border);border-radius:8px;padding:9px 10px;background:var(--ui-surface);color:inherit;font:inherit}.button{border:1px solid var(--ui-border);background:var(--ui-surface);color:var(--ui-text);padding:8px 12px;border-radius:8px;font:inherit;cursor:pointer}.button:disabled{opacity:.5;cursor:not-allowed}.primary{background:var(--ui-btn);color:var(--ui-text-on-btn);border-color:var(--ui-btn)}.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.link{background:none;border:0;color:var(--ui-ink);cursor:pointer;font:inherit;padding:6px}.danger{color:var(--ui-danger)}summary{cursor:pointer;color:var(--ui-text-secondary);font-size:12px}details>p{font-size:12px;line-height:1.7;color:var(--ui-text-secondary)}.check{display:flex;align-items:center;gap:7px;padding:6px 0}.check small{margin-left:auto}.local-head{margin-top:24px}.local-list{list-style:none;padding:0;margin:12px 0}.local-list button{width:100%;text-align:left;border:1px solid transparent;background:none;padding:12px;border-radius:8px;color:inherit;cursor:pointer}.local-list button.selected{background:var(--ui-soft);border-color:var(--ui-border)}.local-list strong,.local-list small{display:block;overflow-wrap:anywhere}.local-list small{margin-top:6px}.badge{font-size:11px;color:var(--ui-text-secondary);white-space:nowrap}.desktop-preview{position:relative;height:220px;border:1px solid var(--ui-border);border-radius:12px;margin-top:18px;background:var(--ui-surface);overflow:hidden}.preview-wall{position:absolute;left:14px;top:12px;font-size:11px;color:var(--ui-text-secondary);max-width:80%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.preview-widget{position:absolute;min-width:50px;padding:12px;border:1px solid var(--ui-border);border-radius:10px;background:var(--ui-soft);color:var(--ui-ink);font-size:11px}.preview-effect{position:absolute;bottom:12px;right:14px;font-size:11px;color:var(--ui-text-secondary)}.reference{display:block;text-align:left;width:100%;padding:10px 0;background:none;border:0;border-bottom:1px solid var(--ui-border);color:var(--ui-ink);cursor:pointer;font:inherit}.cloud{margin-top:28px;padding-top:24px;border-top:1px solid var(--ui-border)}.cloud>.button+.button{margin-left:8px}.remote{border:1px solid var(--ui-border);border-radius:10px;padding:14px;margin-top:16px}.remote h3{margin:0}.notice,.confirm{border:1px solid var(--ui-border);border-radius:10px;padding:14px;margin-bottom:20px;background:var(--ui-soft);white-space:pre-wrap}.notice.error{color:var(--ui-danger)}.confirm p{line-height:1.8}.empty{padding-block:18px;line-height:1.8}@media(max-width:720px){.schemes-window{padding:18px}.workspace{grid-template-columns:1fr}.workspace>aside{border-right:0;padding-right:0;border-bottom:1px solid var(--ui-border)}.detail-heading{flex-wrap:wrap}.local-list{display:flex;overflow:auto}.local-list li{min-width:160px}.desktop-preview{height:180px}}
</style>
